    30|/** The seven buyer categories IVX classifies discovered entities into. */
    31|export type BuyerType =
    32|  | 'cash_buyer'
    33|  | 'family_office'
    34|  | 'developer'
    35|  | 'operator'
    36|  | 'acquisition_group'
    37|  | 'broker'
    38|  | 'reit';
