   102|
   103|/**
   104| * Deterministically classify a discovered entity into a buyer type using only
   105| * public filing data (entity name + declared industry group). Pure + ordered:
   106| * the most specific signals win first. Returns the matched signal for proof.
   107| */
   108|export function classifyBuyerType(investor: DiscoveredInvestor): {
   109|  buyerType: BuyerType;
   110|  classificationSignal: string;
   111|} {
   112|  const name = investor.entityName ?? '';
   113|  const industry = (investor.industryGroup ?? '').toLowerCase();
   114|
   115|  // REIT — strongest, most specific signal.
   116|  const reitToken = nameHas(name, 'REIT', 'Real Estate Investment Trust');
