   118|    return { buyerType: 'reit', classificationSignal: reitToken ?? `industry:${industry}` };
   119|  }
   120|
   121|  // Family office.
   122|  const familyToken = nameHas(name, 'Family Office', 'Family Partners', 'Family Holdings', 'Family Trust');
   123|  if (familyToken) {
   124|    return { buyerType: 'family_office', classificationSignal: familyToken };
   125|  }
   126|
   127|  // Broker / realty / brokerage.
   128|  const brokerToken = nameHas(name, 'Brokerage', 'Realty', 'Realtors', 'Brokers');
   129|  if (brokerToken) {
   130|    return { buyerType: 'broker', classificationSignal: brokerToken };
   131|  }
   132|
   133|  // Developer.
   134|  const developerToken = nameHas(name, 'Development', 'Developers', 'Developer', 'Builders', 'Homes', 'Construction');
   135|  if (developerToken) {
   136|    return { buyerType: 'developer', classificationSignal: developerToken };
   137|  }
   138|
   139|  // Operator (property/asset operations).
   140|  const operatorToken = nameHas(name, 'Operating', 'Operators', 'Management', 'Property Management', 'Communities', 'Residential');
   141|  if (operatorToken) {
   142|    return { buyerType: 'operator', classificationSignal: operatorToken };
   143|  }
   144|
   145|  // Acquisition group / fund / capital vehicle.
   146|  const acqToken = nameHas(
   147|    name,
   148|    'Acquisition',
   149|    'Acquisitions',
   150|    'Capital',
   151|    'Partners',
   152|    'Fund',
   153|    'Equity',
   154|    'Ventures',
   155|    'Holdings',
   156|    'Group',
   157|  );
   158|  if (acqToken) {
   159|    return { buyerType: 'acquisition_group', classificationSignal: acqToken };
   160|  }
   161|
   162|  // Default: a real-estate private-capital entity with no narrower signal.
   163|  return { buyerType: 'cash_buyer', classificationSignal: 'default:private-capital-entity' };
   164|}
   165|
   166|function emptyCounts(): Record<BuyerType, number> {
   167|  return {
   168|    cash_buyer: 0,
   169|    family_office: 0,
   170|    developer: 0,
