   182|
   183|/**
   184| * Discover and classify real buyer entities from public SEC Form D filings.
   185| * Returns an honest `ok:false` + reason on failure; never throws.
   186| */
   187|export async function discoverBuyers(options: BuyerDiscoveryOptions = {}): Promise<BuyerDiscoveryResult> {
   188|  const requestedTypes = normalizeRequestedTypes(options.buyerTypes);
   189|  const discovery = await discoverInvestors({
   190|    query: options.query ?? 'real estate',
   191|    discoveryClass: options.discoveryClass ?? 'buyers',
   192|    minOfferingUsd: options.minOfferingUsd,
   193|    limit: options.limit,
