     1|/**
     2| * IVX Investor Discovery Engine — REAL named investors/buyers from public SEC filings.
     3| *
     4| * This is the LEGAL, verifiable alternative to harvesting private individuals'
     5| * personal contact data (which is illegal under GDPR/CCPA/TCPA and an App Store
     6| * rejection). Every U.S. Reg D private placement is filed publicly with the SEC on
     7| * Form D, and the full filing — including the issuer's real legal name, the real
     8| * names of its executives/directors/promoters (related persons), the business
     9| * address, the offering amount, the number of investors already in, and the filing
    10| * date — is a public record at sec.gov.
    11| *
    12| * This engine queries SEC EDGAR's full-text search for Form D filings, then parses
    13| * each filing's `primary_doc.xml` to extract REAL, attributable records. Nothing is
    14| * fabricated: every record carries a direct link to the official SEC filing so the
    15| * owner can verify it. Records with no real offering amount are kept null, never
    16| * invented.
    17| *
    18| * Two discovery classes (per the owner's request):
    19| *   - `buyers`    → high-value raises (default min offering $10,000,000) — the
    20| *                   entities and principals actively deploying large capital.
    21| *   - `jv_deals`  → any real investor entity (no minimum) filing Reg D offerings,
    22| *                   useful for JV / co-invest sourcing.
    23| *
    24| * Read-only. No personal mobile numbers, no scraped private data — only the
    25| * business contact information the filer chose to make public on a federal form.
    26| */
    27|
    28|/** SEC requires a descriptive User-Agent with contact info on every request. */
    29|const SEC_USER_AGENT = 'IVX Holdings investor-research contact@ivxholding.com';
    30|const EDGAR_FULLTEXT_URL = 'https://efts.sec.gov/LATEST/search-index';
    31|const SEC_ARCHIVES_BASE = 'https://www.sec.gov/Archives/edgar/data';
    32|const FETCH_TIMEOUT_MS = 15_000;
    33|/** SEC fair-access guidance is ~10 req/s; we stay well under it. */
    34|const DETAIL_FETCH_DELAY_MS = 140;
    35|
    36|export type InvestorDiscoveryClass = 'buyers' | 'jv_deals';
    37|
    38|/** A real person named on a public Form D filing (executive / director / promoter). */
    39|export type RelatedPerson = {
    40|  firstName: string;
    41|  lastName: string;
    42|  fullName: string;
    43|  relationships: string[];
    44|  city: string | null;
    45|  stateOrCountry: string | null;
