   151|/** Extract the text content of the FIRST occurrence of <tag>...</tag>. */
   152|function firstTag(xml: string, tag: string): string | null {
   153|  const match = xml.match(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`, 'i'));
   154|  const value = match?.[1]?.trim();
   155|  return value && value.length > 0 ? decodeXml(value) : null;
   156|}
   157|
   158|function decodeXml(value: string): string {
   159|  return value
   160|    .replace(/&amp;/g, '&')
   161|    .replace(/&lt;/g, '<')
   162|    .replace(/&gt;/g, '>')
   163|    .replace(/&quot;/g, '"')
   164|    .replace(/&apos;/g, "'")
   165|    .trim();
   166|}
   167|
   168|function toNumber(value: string | null): number | null {
   169|  if (!value) return null;
   170|  const cleaned = value.replace(/[^0-9.]/g, '');
   171|  if (!cleaned) return null;
   172|  const n = Number(cleaned);
   173|  return Number.isFinite(n) && n > 0 ? Math.round(n) : null;
   174|}
   175|
   176|/** Parse the `<relatedPersonsList>` block into real named principals. */
   177|export function parseRelatedPersons(xml: string): RelatedPerson[] {
   178|  const listMatch = xml.match(/<relatedPersonsList>([\s\S]*?)<\/relatedPersonsList>/i);
   179|  if (!listMatch) return [];
   180|  const block = listMatch[1];
   181|  const people: RelatedPerson[] = [];
   182|  const personRegex = /<relatedPersonInfo>([\s\S]*?)<\/relatedPersonInfo>/gi;
   183|  let m: RegExpExecArray | null;
   184|  while ((m = personRegex.exec(block)) !== null) {
   185|    const chunk = m[1];
   186|    const first = firstTag(chunk, 'firstName') ?? '';
   187|    const last = firstTag(chunk, 'lastName') ?? '';
   188|    const fullName = [first, last].filter(Boolean).join(' ').trim();
   189|    if (!fullName) continue;
   190|    const relationships: string[] = [];
   191|    const relRegex = /<relationship>([\s\S]*?)<\/relationship>/gi;
   192|    let r: RegExpExecArray | null;
   193|    while ((r = relRegex.exec(chunk)) !== null) {
   194|      const rel = decodeXml(r[1]);
   195|      if (rel) relationships.push(rel);
   196|    }
   197|    people.push({
   198|      firstName: first,
   199|      lastName: last,
   200|      fullName,
   201|      relationships,
   202|      city: firstTag(chunk, 'city'),
   203|      stateOrCountry: firstTag(chunk, 'stateOrCountry'),
