   212|/** Score a discovered investor 0–100 with explainable reasons. Pure + testable. */
   213|export function scoreDiscoveredLead(
   214|  investor: DiscoveredInvestor,
   215|  industryQuery: string,
   216|): { score: number; reasons: string[] } {
   217|  const reasons: string[] = [];
   218|  let score = 0;
   219|
   220|  // Capital size (up to 40): bigger disclosed offerings rank higher.
   221|  const amount = investor.totalOfferingAmountUsd;
   222|  if (amount !== null && amount > 0) {
   223|    const capitalPoints = Math.round(Math.min(1, amount / MAX_OFFERING_FOR_SCALE) * 40);
   224|    score += capitalPoints;
   225|    reasons.push(`Disclosed offering $${amount.toLocaleString('en-US')} (+${capitalPoints} capital).`);
   226|  } else {
   227|    reasons.push('Offering amount not disclosed (+0 capital).');
   228|  }
   229|
   230|  // Real named principals (up to 20): more attributable people = stronger lead.
   231|  const principals = investor.relatedPersons.length;
   232|  if (principals > 0) {
   233|    const principalPoints = Math.min(20, principals * 5);
   234|    score += principalPoints;
   235|    reasons.push(`${principals} named principal(s) on the filing (+${principalPoints}).`);
   236|  } else {
   237|    reasons.push('No named principals on the filing (+0).');
   238|  }
   239|
   240|  // Recency (up to 20): a filing in the last 18 months is more actionable.
   241|  if (investor.filingDate) {
   242|    const filed = Date.parse(investor.filingDate);
   243|    if (Number.isFinite(filed)) {
   244|      const monthsAgo = (Date.now() - filed) / (1000 * 60 * 60 * 24 * 30);
   245|      const recencyPoints = monthsAgo <= 18 ? Math.round((1 - monthsAgo / 18) * 20) : 0;
   246|      score += recencyPoints;
   247|      reasons.push(`Filed ${Math.max(0, Math.round(monthsAgo))} month(s) ago (+${recencyPoints} recency).`);
   248|    }
   249|  } else {
   250|    reasons.push('Filing date unknown (+0 recency).');
   251|  }
   252|
   253|  // Industry match (up to 15): industry group aligns with the search intent.
   254|  const query = industryQuery.trim().toLowerCase();
   255|  const industry = (investor.industryGroup ?? '').toLowerCase();
   256|  if (query && industry && (industry.includes(query) || query.includes(industry))) {
   257|    score += 15;
   258|    reasons.push(`Industry "${investor.industryGroup}" matches the search (+15).`);
   259|  } else if (industry) {
